# Let's try a simple backtracking search for L(2,11)
n = 11
length = 2 * n

def solve_langford(n):
    seq = [0] * (2 * n)
    # positions where value v can be placed: we need two positions p and p+v+1
    # We'll place values from largest to smallest (better pruning)

    def backtrack(v):
        if v == 0:
            return True
        # Try to place value v
        for p in range(2 * n - v - 1):
            if seq[p] == 0 and seq[p + v + 1] == 0:
                seq[p] = v
                seq[p + v + 1] = v
                if backtrack(v - 1):
                    return True
                seq[p] = 0
                seq[p + v + 1] = 0
        return False

    if backtrack(n):
        return seq
    return None

result = solve_langford(11)
print("Result:", result)
if result:
    # Verify
    for v in range(1, n+1):
        positions = [i for i, x in enumerate(result) if x == v]
        print(f"Value {v}: positions {positions}, distance = {positions[1] - positions[0]}")
else:
    print("No solution found")
